// === Tab: Can ===
class Can {
	constructor(x, y, size, id) {
		this.x = x;
		this.y = y;
		this.a = 0;
		this.av = random(-1, 1);
		if (abs(this.av) < 0.1) this.av = random(0.1, 0.9);
		this.size = size;
		this.crush = 3.2;
		this.tcrush = 3.2;
		this.flip = 0;
		this.tflip = random(10, 85);
		this.id = id;
	}
	show() {
		push();
		shininess(2);
		translate(this.x, this.y + (1.5 * this.size), 0);
		translate(0, -(0.5 * this.crush * this.size), 0);
		rotateX(this.a);
		rotateY(75 + this.a);
		noStroke();
		texture(img);

		cylinder(1.1 * this.size, this.crush * this.size, 24, 1, false, false);

		specularMaterial(150);
		cylinder(1.09 * this.size, this.crush * this.size, 24, 1, false, true);
		translate(0, (1.01 * this.crush / 2) * this.size, 0);
		push();
		rotateX(90);
		torus(0.9 * this.size, 0.02 * this.size, 72, 12);
		torus(0.7 * this.size, 0.02 * this.size, 72, 12);
		specularMaterial(180);
		torus(1.08 * this.size, 0.04 * this.size, 72, 12);
		pop();
		translate(0, -1.01 * this.crush * this.size, 0);
		push();
		rotateX(90);
		specularMaterial(130);
		torus(1.08 * this.size, 0.04 * this.size, 72, 12);
		translate(1.08 * this.size, 0, 0);
		rotateY(this.flip);
		translate(-1.08 * this.size, 0, 0);
		rotateX(this.flip / 3);

		push();
		rotateX(-90);
		cylinder(1.08 * this.size, 1);
		pop();
		torus(0.9 * this.size, 0.03 * this.size, 72, 12);
		torus(0.7 * this.size, 0.03 * this.size, 72, 12);
		specularMaterial(180);
		pop();
		pop();
	}
	move() {
		this.a += this.av;
	}
	smush() {
		//this.tflip += (0.5 - noise(this.id + frameCount / 100));
		this.crush = lerp(this.crush, this.tcrush, 0.4);
		this.flip = lerp(this.flip, this.tflip, 0.4);
	}
	upright() {
		this.a = lerp(this.a, 0, 0.1);
	}
}

// === Tab: mySketch ===
// For the #WCCChallenge, theme: "flat"
// This extends (recycles?) a sketch I made a few years ago, when I first started
// experimenting with WEBGL. It's always fun for me to look back at an old sketch
// and notice all the things I've learned to do differently over the years!
// (May suffer from audio distortion over time.)

var img, sound;
var cans = [];

var xpos = 0;
var zpos = 0;

var lpos, mpos;
var paused = true;
var upright = false;
var count = 0;

var rows = 3;
var cols = 9;

function preload() {
	img = loadImage('file:///Users/unclerm/Vibe Coding/4K MV Visual Integration Editor/assets_cache/souplabel.jpg');
	sound = loadSound('file:///Users/unclerm/Vibe Coding/4K MV Visual Integration Editor/assets_cache/default_texture.png');
}

function setup() {
	createCanvas(windowWidth, windowHeight, WEBGL);
	angleMode(DEGREES);
	let cid = 30;
	let cansize = height / (6*rows);
	let yspacing = 6*cansize;
	let xspacing = yspacing / 1.5;
	for (row = 0; row < rows; row++) {
		for (col = 0; col < cols; col++) {
			let x = -((cols - 1) / 2) * xspacing + (col * xspacing);
			let y = -((rows - 1) / 2) * yspacing + (row * yspacing);
			cans.push(new Can(x, y, cansize, cid));
			cid += 3;
		}
	}
	zpos = -1.25 * height;
	lpos = createVector(0, 0);
	mpos = createVector((window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))), (window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))));
}

function draw() {
	translate(0, height / 24);
	background('rgb(133,17,15)');
	setLighting();
	moveCamera();
	for (c of cans) {
		if (paused == false) {
			c.move();
		} else if (upright) {
			c.upright();
		}
		if (c.id < frameCount) c.smush();
		c.show();
	}
}

function setLighting() {
	ambientLight(195, 155, 155);
	mpos.x = (window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))) - width / 2;
	mpos.y = (window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))) - height / 2;
	lpos.lerp(mpos, 0.1);
	pointLight(100, 100, 100, lpos.x, lpos.y, 250);
}

function moveCamera() {
	xpos = lerp(xpos, map((window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))), 0, width, 2 * height, -2 * height), 0.1);
	zpos = lerp(zpos, map((window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))), height, 0, 1.25*height, -1.25*height), 0.1);
	camera(xpos, 0, zpos, 0, 0, 0, 0, 1, 0);
}

function keyPressed() {
	if (keyCode == 32) {
		paused = !paused;
		upright = false;
	}
	if (keyCode == 13) {
		paused = true;
		upright = true;
	}
}

function mousePressed() {
	if (count < cans.length) {
		paused = false;
		upright = false;
		let c = random(cans);
		while (c.tflip < 10) c = random(cans);
		sound.rate(random(0.75, 2.5));
		sound.pan(map(c.x, -width / 2, width / 2, -1, 1))
		sound.play();
		c.tcrush = random(0.15, 0.5);
		c.tflip = random(10);
		count++;
	} else {
		for (c of cans) {
			paused = true;
			sound.pan(map(c.x, -width / 2, width / 2, -1, 1));
			sound.play();
			c.tcrush = 3.2;
			c.flip = 0;
			c.tflip = random(10, 85);
			count = 0;
		}
		setTimeout(reorganize, 1000);
	}
}

function reorganize() {
	upright = true;
}
